"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The a bundle of letters of the Yorkshire moors', 'author': 'Signature original', 'genre': 'Jazz Age', 'chapters': [{'n': 1, 'title': 'The Discovery', 'text': "Yet Thomas Beckett kept returning to a bundle of letters, the way one returns to a sore tooth. It told a story — of a debt unpaid, a promise broken, a life ruined. And stories, Thomas Beckett was beginning to understand, are a kind of debt themselves.\n\nBut a bundle of letters would not be ignored. That night, by gaslight, Thomas Beckett examined it: the handwriting, the seal, the date — twenty years gone. And the name. The name that the factory boss had paid good money to bury.\n\nthe seamstress listened, wide-eyed, over cold tea. 'You can't show that to anyone,' the seamstress whispered. 'Do you know what the factory boss does to people who talk?' Thomas Beckett knew. Everyone in the Yorkshire moors knew."}, {'n': 2, 'title': 'Inquiries', 'text': "Thomas Beckett began carefully, as one must in the Yorkshire moors: a question to the vicar, a look at the parish register, a conversation with the old soldier who remembered everything and forgave nothing.\n\nEach answer was a thread, and the threads wove the factory boss's tapestry: the mill, the accident, the silenced witnesses, the money that flowed like a dirty river through the Yorkshire moors. a bundle of letters was the loose end.\n\nthe factory boss noticed. A carriage followed Thomas Beckett home. A note arrived: 'Some things are better left buried.' Thomas Beckett burned the note and kept digging. Buried things, Thomas Beckett had learned, have a way of surfacing."}, {'n': 3, 'title': 'The Witness', 'text': "The magistrate was the factory boss's man; the papers were the factory boss's papers. But a bundle of letters was Thomas Beckett's, and the witness was real, and the truth — Thomas Beckett clung to this — the truth is stubborn in any century.\n\nthe factory boss struck that night: a break-in, a fire set to frighten, a thug with a message written in bruises. the seamstress took the worst of it and joked through split lips. Thomas Beckett wept and planned.\n\nThomas Beckett wrote it all down, every thread, every name, and sealed it three ways. If the factory boss silenced them, the story would still speak. the past shapes us — even in the Yorkshire moors, even then."}, {'n': 4, 'title': 'The Reckoning', 'text': "Thomas Beckett stood in the emptying hall with a bundle of letters and felt not triumph but tiredness, and under it, peace. the past shapes us. It had cost plenty. It was worth it.\n\nIt came to a head at the assembly rooms, in front of all the Yorkshire moors: Thomas Beckett stood and spoke, with a bundle of letters held high and the witness beside them. The gaslight seemed to lean in to listen.\n\nThe magistrate squirmed. The crowd — the Yorkshire moors's people, mill hands and merchants' wives — began to murmur, and the murmur became a voice. the factory boss's money couldn't buy this room. Not tonight."}, {'n': 5, 'title': 'Restoration', 'text': "the seamstress married the vicar's son — or daughter; the Yorkshire moors gossiped happily either way — and named their first child after Thomas Beckett, who pretended to mind and didn't.\n\nYears later, Thomas Beckett would show a bundle of letters to the curious and say: 'This is what courage looks like when it's old and paper.' And the young would listen, and the Yorkshire moors would remember.\n\nthe past shapes us — Thomas Beckett had it carved, finally, on no monument at all, just lived it, in the Yorkshire moors, in every ordinary, extraordinary day."}, {'n': 6, 'title': 'Coda: The Drawer', 'text': "the factory boss is a name in the records, a caution. the Yorkshire moors is a place where the mills run fair and the magistrate is honest, mostly, which is as much as any age can ask.\n\na bundle of letters rests now in Thomas Beckett's drawer, among the bills and the birthday cards. Sometimes Thomas Beckett takes it out, just to hold the weight of it: proof that one person, in the Yorkshire moors, in any age, can tip the scales.\n\nthe past shapes us. In the Yorkshire moors, in every place, in every age. The end — which is to say, the beginning."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

